SELECT snapshot_date
FROM analytics_recommendation_result
WHERE scene = #{scene}
  AND user_id = #{userId}
ORDER BY snapshot_date DESC
LIMIT 1

SELECT *
FROM analytics_recommendation_result
WHERE scene = #{scene}
  AND user_id = #{userId}
  AND snapshot_date = #{snapshotDate}
ORDER BY rank_no ASC
LIMIT #{limit}
